1	import { execFileSync, execSync, spawnSync } from "node:child_process";
2	import * as path from "node:path";
3	import { PATHSPEC_MODE_ENV, verifyCheckout } from "./core/checkout_trust.js";
4	import { nestedRepositoryReason } from "./worktrunk/git.js";
5	import * as fs from "node:fs";
6	
7	export interface GitInfo {
8	  isRepo: boolean;
9	  branch: string;
10	  dirtyCount: number;
11	  formattedBadge: string;
12	  /** Set when Git was refused (a worktree the sandboxed agent could have tampered with), so the cause is not mistaken for "not a repository". */
13	  refusal?: string;
14	}
15	
16	/**
17	 * Nexus's own state directories: the workspace's `.nexus` and the repository root's. Status reads the whole repository
18	 * without them, and commitChanges unstages and excludes exactly the same set, so the header, the model's [Git Status]
19	 * line, /git and /commit agree and Nexus's receipts never count as, or get committed with, a user change.
20	 * A file the user deliberately tracks under `.nexus/` is therefore not reported or committed by Nexus either.
21	 */
22	const NEXUS_STATE = [".nexus", ":(top).nexus"];
23	const NEXUS_STATE_EXCLUDED = [":(exclude).nexus", ":(exclude).nexus/**", ":(top,exclude).nexus", ":(top,exclude).nexus/**"];
24	const WITHOUT_NEXUS_STATE = ["--", ":/", ...NEXUS_STATE_EXCLUDED];
25	
26	/** The environment for git calls that pass the pathspecs above: an inherited pathspec mode would make them literal. */
27	function pathspecEnv(): NodeJS.ProcessEnv {
28	  const env = { ...process.env };
29	  for (const key of PATHSPEC_MODE_ENV) delete env[key];
30	  return env;
31	}
32	
33	/**
34	 * Host-side Git must not run in a worktree whose `.git` (or a nested repository) the sandboxed agent could have planted.
35	 * Returns the `--git-dir`/`--work-tree` pair to run Git against (empty for a plain repository), so a pointer rewritten
36	 * after this check is not re-read.
37	 */
38	function trustedGitArgs(workspace: string): string[] {
39	  const checkout = verifyCheckout(workspace);
40	  const reason = checkout.reason ?? nestedRepositoryReason(workspace); // the checkout itself, and any repository planted below it
41	  if (reason) throw new Error(`refusing to run Git in ${workspace}: it is not a trusted worktree (${reason})`);
42	  return checkout.gitDir ? ["--git-dir", checkout.gitDir, "--work-tree", checkout.workTree!] : [];
43	}
44	
45	/** `git status` in `format` for the workspace's repository, without Nexus state. Throws when git fails. */
46	export function workspaceStatus(workspace: string, format: "--porcelain" | "--short"): string {
47	  return execFileSync("git", [...trustedGitArgs(workspace), "status", format, ...WITHOUT_NEXUS_STATE], {
48	    cwd: workspace,
49	    env: pathspecEnv(),
50	    encoding: "utf-8",
51	    stdio: ["ignore", "pipe", "pipe"],
52	    maxBuffer: 64 * 1024 * 1024,
53	  });
54	}
55	
56	/** The current branch; on an unborn branch (no commit yet) `rev-parse` fails, so read the symbolic ref instead. */
57	function currentBranch(workspace: string): string {
58	  const pin = trustedGitArgs(workspace);
59	  const run = (args: string[]) =>
60	    execFileSync("git", [...pin, ...args], { cwd: workspace, encoding: "utf-8", stdio: ["ignore", "pipe", "ignore"] }).trim();
61	  try {
62	    return run(["rev-parse", "--abbrev-ref", "HEAD"]);
63	  } catch {
64	    return run(["symbolic-ref", "--short", "HEAD"]);
65	  }
66	}
67	
68	export function getGitInfo(workspace: string): GitInfo {
69	  try {
70	    const statusOut = workspaceStatus(workspace, "--porcelain").trim(); // guards the checkout before any Git runs
71	    const branch = currentBranch(workspace);
72	
73	    const lines = statusOut ? statusOut.split("\n") : [];
74	    const dirtyCount = lines.length;
75	
76	    const formattedBadge = dirtyCount > 0 ? `${branch} *${dirtyCount}` : branch;
77	
78	    return {
79	      isRepo: true,
80	      branch,
81	      dirtyCount,
82	      formattedBadge,
83	    };
84	  } catch (err) {
85	    const message = (err as Error)?.message ?? "";
86	    return {
87	      isRepo: false,
88	      branch: "",
89	      dirtyCount: 0,
90	      formattedBadge: "",
91	      ...(message.startsWith("refusing to run Git") ? { refusal: message } : {}),
92	    };
93	  }
94	}
95	
96	export function getProjectRules(workspace: string): string | null {
97	  const candidates = [
98	    "AGENTS.md",
99	    "CLAUDE.md",
100	    "CODEX.md",
101	    ".nexusrules",
102	  ];
103	
104	  for (const filename of candidates) {
105	    const fullPath = path.join(workspace, filename);
106	    if (fs.existsSync(fullPath)) {
107	      try {
108	        const content = fs.readFileSync(fullPath, "utf-8").trim();
109	        if (content) {
110	          return `### Project Instructions (loaded from ${filename}):\n${content}`;
111	        }
112	      } catch {
113	        // ignore read error
114	      }
115	    }
116	  }
117	
118	  return null;
119	}
120	
121	export function scaffoldProjectRules(workspace: string): string {
122	  const target = path.join(workspace, "AGENTS.md");
123	  if (fs.existsSync(target)) {
124	    return target;
125	  }
126	
127	  const template = `# Project Guidelines & Agent Instructions
128	
129	## Commands
130	- Build: \`make build\` or \`cargo build\` or \`npm run build\`
131	- Test: \`make test\` or \`cargo test\` or \`npm test\`
132	- Lint: \`cargo clippy\` or \`npm run lint\`
133	
134	## Code Conventions
135	- Maintain documentation integrity and keep existing comments.
136	- Always run tests after making changes to verify correctness.
137	- Keep functions modular and clearly typed.
138	`;
139	
140	  fs.writeFileSync(target, template, "utf-8");
141	  return target;
142	}
143	
144	export function generateConventionalCommit(workspace: string): { message: string; files: string[] } {
145	  try {
146	    const statusOut = workspaceStatus(workspace, "--porcelain").trimEnd();
147	
148	    if (!statusOut) {
149	      return { message: "chore(repo): update repository", files: [] };
150	    }
151	
152	    const lines = statusOut.split("\n");
153	    const files = lines.map((l) => l.slice(3).trim());
154	    return { message: conventionalCommitMessage(files), files };
155	  } catch {
156	    return { message: "chore(repo): update workspace", files: [] };
157	  }
158	}
159	
160	/** The deterministic conventional-commit subject for a list of changed paths (no Git, no shell). */
161	export function conventionalCommitMessage(files: string[]): string {
