104	  let budget = MAX_UNTRACKED_ENTRIES_SCANNED;
105	  for (const entry of listing(["ls-files", "-o", "--exclude-standard", "--directory", "-z"])) {
106	    if (!entry.endsWith("/")) continue;
107	    const found = gitDirectoriesBelow(path.join(dir, entry), budget);
108	    if (found === undefined) return `more than ${MAX_UNTRACKED_ENTRIES_SCANNED} entries sit in untracked directories below ${dir}; none can be checked for a planted repository`;
