121	/** Directories at or below `root` that hold a `.git`, and how many entries were read; undefined when `budget` runs out. */
122	function gitDirectoriesBelow(root: string, budget: number): { repos: string[]; scanned: number } | undefined {
123	  const repos: string[] = [];
124	  const pending = [root];
125	  let scanned = 0;
126	  while (pending.length > 0) {
127	    const dir = pending.pop()!;
128	    let names: fs.Dirent[];
129	    try { names = fs.readdirSync(dir, { withFileTypes: true }); } catch { continue; }
130	    for (const entry of names) {
131	      if (++scanned > budget) return undefined;
132	      if (entry.name === ".git") repos.push(dir);
133	      else if (entry.isDirectory()) pending.push(path.join(dir, entry.name));
134	    }
135	  }
136	  return { repos, scanned };
137	}
