158	  const pin = checkout.gitDir ? ["--git-dir", checkout.gitDir, "--work-tree", checkout.workTree!] : [];
159	  const result = spawnSync("git", [...PINNED_GIT_FLAGS, ...pin, ...args], {
160	    cwd,
161	    encoding: "utf8",
162	    stdio: ["pipe", "pipe", "pipe"],
163	    input: options.input ?? "",
164	    env: { ...baseEnv(), ...(options.env ?? {}) },
165	    timeout: options.timeoutMs ?? 30_000,
166	    maxBuffer: options.maxBuffer ?? 32 * 1024 * 1024,
167	  });
168	  const timedOut = (result.error as NodeJS.ErrnoException | undefined)?.code === "ETIMEDOUT";
169	  const out: GitResult = { status: result.status, stdout: result.stdout ?? "", stderr: result.stderr ?? "", timedOut };
170	  if (result.error && !timedOut) throw new GitError(`git could not run: ${(result.error as Error).message}`, null, args);
